import {expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// specs/hal-engine-config-hooks/spec.md#7
it('runs cleanup before any provider interaction when beforeSession fails', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const error = new Error('setup failed');
  const events: string[] = [];
  const provider: AIProvider = {
    async *sendMessage() {
      events.push('provider');
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
    hooks: {
      beforeSession: async () => { throw error; },
      onError: async (receivedSession, receivedError) => {
        if (receivedSession === session && receivedError === error) events.push('onError');
      },
      afterSession: async receivedSession => {
        if (receivedSession === session) events.push('afterSession');
      },
    },
  });

  await orchestrator.processMessage(session).catch(() => undefined);
  expect(events).toEqual(['onError', 'afterSession']);
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/chatOrchestrator.beforeSession.cleanup.test.ts"
